<file path="src/invoices.js">
import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

function isValidDate(dateString) {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(dateString)) return false;

  const date = new Date(dateString + 'T00:00:00Z');
  if (isNaN(date.getTime())) return false;

  const [year, month, day] = dateString.split('-').map(Number);
  if (date.getUTCFullYear() !== year ||
      date.getUTCMonth() + 1 !== month ||
      date.getUTCDate() !== day) {
    return false;
  }

  return true;
}

/**
 * Create an invoice with the given customer, issue date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || !Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line item: qty times unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || typeof line.qty !== 'number' || typeof line.unitPrice !== 'number') {
    return fail('LINE_INVALID');
  }
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice: subtotal (sum of line totals) and total (equals subtotal for now).
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
 * @returns {{ ok: true, value: { subtotal: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  for (const line of invoice.lines) {
    const result = lineTotal(line);
    if (!result.ok) return result;
    subtotal += result.value;
  }

  return ok({
    subtotal,
    total: subtotal,
  });
}

/**
 * Add or increase a line item on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number }>, customerId: string, issueDate: string }} invoice
 * @param {{ sku: string, qty: number }}
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    lines: newLines,
  });
}

/**
 * Remove a line item from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }>, customerId: string, issueDate: string }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.map((line) => ({ ...line })).filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'draft',
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a unique number and changing status to 'issued'.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers - All invoice numbers already issued
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}
</file>

<file path="src/money.js">
import { ok, fail } from './result.js';

/**
 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
 * @param {number} x
 * @returns {number}
 */
export function roundCents(x) {
  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
  const floor = Math.floor(r);
  const diff = r - floor;
  if (diff > 0.5) return floor + 1;
  if (diff < 0.5) return floor === 0 ? 0 : floor;
  return floor % 2 === 0 ? floor : floor + 1;
}

/**
 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
 * @param {number} cents
 * @returns {string}
 */
export function formatEuros(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
}

/**
 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
 * @param {string} text
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function parseEuros(text) {
  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
  if (!m) return fail('AMOUNT_INVALID');
  const euros = Number(m[1].replace(/,/g, ''));
  const cents = Number((m[2] ?? '').padEnd(2, '0'));
  return ok(euros * 100 + cents);
}
</file>

<file path="src/numbering.js">
/**
 * Calculate the next free invoice number for a given year.
 * Numbers have format INV-<year>-<counter> where counter is 4 digits, zero-padded.
 * @param {Array<string>} existingNumbers - Invoice numbers already used, in any order
 * @param {string} issueDate - Issue date in YYYY-MM-DD format
 * @returns {string}
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.split('-')[0];
  const prefix = `INV-${year}-`;

  const countersThisYear = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => parseInt(num.slice(prefix.length), 10))
    .filter((counter) => !isNaN(counter));

  const maxCounter = countersThisYear.length > 0 ? Math.max(...countersThisYear) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}
</file>

<file path="src/render.js">
import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * Format: invoice number (or DRAFT), customer name, line items, and total.
 * All amounts are formatted as euros using formatEuros().
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number }> }}
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number ?? 'DRAFT';
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown';

  const lines = [];
  lines.push(number);
  lines.push(customerName);

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const formattedUnitPrice = formatEuros(line.unitPrice);
    const formattedLineTotal = formatEuros(lineTotal);
    lines.push(`${line.qty} × ${line.name} @ ${formattedUnitPrice} = ${formattedLineTotal}`);
  }

  const totalsResult = invoiceTotals(invoice);
  const totalAmount = totalsResult.ok ? totalsResult.value.total : 0;
  const formattedTotal = formatEuros(totalAmount);
  lines.push(`Total: ${formattedTotal}`);

  return lines.join('\n');
}
</file>

<file path="src/result.js">
/**
 * A successful result.
 * @template T
 * @param {T} value
 * @returns {{ ok: true, value: T }}
 */
export function ok(value) {
  return { ok: true, value };
}

/**
 * A failed result. `error` is an error code from ERRORS in src/errors.js.
 * @param {string} error
 * @param {unknown} [details]
 * @returns {{ ok: false, error: string, details?: unknown }}
 */
export function fail(error, details) {
  return details === undefined ? { ok: false, error } : { ok: false, error, details };
}
</file>

<file path="test/catalogue.test.js">
import test from 'node:test';
import assert from 'node:assert/strict';
import { listProducts, getProduct } from '../src/catalogue.js';

test('every product has a whole-cent price and a known VAT rate', () => {
  for (const p of listProducts()) {
    assert.ok(Number.isInteger(p.unitPrice) && p.unitPrice > 0, p.sku);
    assert.ok([0, 9, 21].includes(p.vatRate), p.sku);
  }
});

test('getProduct finds a product by SKU', () => {
  const r = getProduct('DES-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.unitPrice, 8500);
});

test('getProduct reports an unknown SKU', () => {
  assert.deepEqual(getProduct('NOPE'), { ok: false, error: 'UNKNOWN_SKU' });
});

test('listProducts returns copies', () => {
  listProducts()[0].unitPrice = 1;
  assert.equal(getProduct('DES-HOUR').value.unitPrice, 8500);
});
</file>

